STDF_HELP = [
    "# stdfull - المكتبة القياسية الشاملة: كل ما تبقى من وحدات Python القياسية",
]

_STDF_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _stdfull_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in STDF_CONSTS:
        return STDF_CONSTS[word]
    if word in STDF_FUNCS:
        return STDF_FUNCS[word] + (open_paren or "")
    return match.group(0)


def STDF_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _STDF_TOKEN.sub(_stdfull_replace, text)
